import { useState, useRef, useEffect } from 'react'
import Link from 'next/link'

// items: [{ href, label, items?: [...] }]
export default function Dropdown({ label, href, items = [], className = '' }){
  const [open, setOpen] = useState(false)
  const ref = useRef(null)

  useEffect(()=>{
    function onDocClick(e){ if (!ref.current) return; if (!ref.current.contains(e.target)) setOpen(false) }
    function onEsc(e){ if (e.key === 'Escape') setOpen(false) }
    document.addEventListener('click', onDocClick)
    document.addEventListener('keydown', onEsc)
    return ()=>{ document.removeEventListener('click', onDocClick); document.removeEventListener('keydown', onEsc) }
  },[])

  return (
    <div ref={ref} className={`nav-item has-dropdown ${open? 'open':''} ${className}`}>
      <div className="nav-link-wrap">
        {items && items.length > 0 ? (
          // main label becomes a toggle button when there are subitems
          <button
            type="button"
            className="nav-link nav-link-toggle"
            aria-expanded={open}
            aria-haspopup="true"
            onClick={(e)=>{ e.stopPropagation(); setOpen(s=>!s) }}
          >{label}</button>
        ) : (
          href ? <Link href={href} className="nav-link">{label}</Link> : <span className="nav-link">{label}</span>
        )}
      </div>

      <div className="dropdown-menu" role="menu">
        {items.map(it => (
          it.items ? (
            <div key={it.label} className="dropdown-item has-submenu">
              <Dropdown label={it.label} href={it.href} items={it.items} className="submenu" />
            </div>
          ) : (
            <Link key={it.label} href={it.href} className={`dropdown-item`} onClick={() => setOpen(false)}>{it.label}</Link>
          )
        ))}
      </div>
    </div>
  )
}
